using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Globalization;using SolidWorks.Interop.sldworks;
public class ExportReview {
static string root,work;
static string F(double v){return v.ToString("R",CultureInfo.InvariantCulture);} static string Rel(string p){return p.StartsWith(root,StringComparison.OrdinalIgnoreCase)?p.Substring(root.Length+1).Replace('\\','/'):p;}
public static void Run(int pid,string repository,string cache){root=Path.GetFullPath(repository);work=Path.GetFullPath(cache);var sw=SwRot.Connect(pid);if(sw==null)throw new Exception("PID not registered in ROT");if(sw.GetDocuments()!=null)throw new Exception("Use a dedicated empty SolidWorks session");Console.WriteLine("CONNECTED "+sw.GetProcessID());Directory.CreateDirectory(work+"/meshes");var manifest=new List<string>{"assembly\tconfiguration\tcomponent\tpath\tsuppression\thidden\tmesh\ttransform\tbox"};
foreach(string name in new[]{"holydrone_nx_v1.SLDASM","holydrone_lbc4_v1.SLDASM","holydrone_static_towing_v1.sldasm","holydrone_towing_v1.SLDASM"}) {int e=0,w=0;Console.WriteLine("OPEN "+name);var d=(IModelDoc2)sw.OpenDoc6(root+"/"+name,2,3,"",ref e,ref w);if(d==null){Console.WriteLine("FAILED "+e+" "+w);continue;}Console.WriteLine("OPENED "+e+" "+w);var a=(IAssemblyDoc)d; a.ResolveAllLightWeightComponents(false);var cfg=d.ConfigurationManager.ActiveConfiguration.Name;Console.WriteLine("CFG "+cfg);var cs=(object[])a.GetComponents(false);int count=0;foreach(IComponent2 c in cs){string p=c.GetPathName(),mesh="",box="";int supp=c.GetSuppression();bool hidden=c.IsHidden(true);var tr=c.Transform2;string t=tr==null?"":string.Join(",",((double[])tr.ArrayData).Select(F));if(supp!=0&&p.EndsWith("sldprt",StringComparison.OrdinalIgnoreCase)) {var pd=c.GetModelDoc2() as IModelDoc2;if(pd==null) {int pe=0,pw=0;pd=(IModelDoc2)sw.OpenDoc6(p,1,3,"",ref pe,ref pw);} if(pd!=null){var part=(IPartDoc)pd;var b=(double[])part.GetPartBox(true);if(b!=null)box=string.Join(",",b.Select(F)); if(!hidden&&(name.Contains("nx_v1")||name.Contains("lbc4"))){mesh=Path.GetFileNameWithoutExtension(name)+"_"+count+".bin";var data=(Array)part.GetTessTriangles(true);if(data!=null){using(var bw=new BinaryWriter(File.Create(work+"/meshes/"+mesh))){for(int i=0;i<data.Length;i++)bw.Write(Convert.ToSingle(data.GetValue(i)));}}else mesh="";}}}
manifest.Add(string.Join("\t",new[]{name,cfg,c.Name2,Rel(p),supp.ToString(),hidden.ToString(),mesh,t,box}));count++;}Console.WriteLine("COMPONENTS "+count+" modified="+d.GetSaveFlag());File.WriteAllLines(work+"/assembly-manifest.tsv",manifest,System.Text.Encoding.UTF8);}
Console.WriteLine("COMPLETE");}}
